WITH by_dimension AS (SELECT p.city, s.status, COUNT(*) AS rows_total, SUM(s.monthly_fee) AS total_monthly_fee FROM subscriptions s JOIN customers p ON s.customer_id = p.id GROUP BY CUBE (p.city, s.status)) SELECT city, status, rows_total, total_monthly_fee, CASE WHEN status RLIKE '^(EXPIRED|ACTIVE)$' THEN 'CORE' WHEN status RLIKE '^(CANCELLED|PAUSED)$' THEN 'EXTENDED' ELSE 'GROUP_B' END AS status_zone FROM by_dimension ORDER BY total_monthly_fee DESC NULLS FIRST
